package dev.hrutvik.billing.metering;
import org.apache.kafka.clients.consumer.ConsumerRecord; import org.apache.kafka.common.header.internals.RecordHeader; import org.junit.jupiter.api.Test; import org.springframework.kafka.support.Acknowledgment; import java.nio.charset.StandardCharsets; import java.util.UUID; import static org.mockito.Mockito.*;
class UsageRecordedConsumerTest {
 @Test void acknowledgesOnlyAfterDurableAndRealtimeProjections(){var aggregation=mock(UsageAggregationService.class);var realtime=mock(RealtimeUsageProjection.class);var ack=mock(Acknowledgment.class);var id=UUID.randomUUID();var record=record(id);new UsageRecordedConsumer(aggregation,realtime).consume(record,ack);var order=inOrder(aggregation,realtime,ack);order.verify(aggregation).aggregate(id,"usage",3,19);order.verify(realtime).record(id);order.verify(ack).acknowledge();}
 @Test void redisFailureLeavesKafkaDeliveryUnacknowledged(){var aggregation=mock(UsageAggregationService.class);var realtime=mock(RealtimeUsageProjection.class);var ack=mock(Acknowledgment.class);var id=UUID.randomUUID();doThrow(new RealtimeUsageUnavailable("down",new RuntimeException())).when(realtime).record(id);org.junit.jupiter.api.Assertions.assertThrows(RealtimeUsageUnavailable.class,()->new UsageRecordedConsumer(aggregation,realtime).consume(record(id),ack));verifyNoInteractions(ack);}
 private ConsumerRecord<String,String> record(UUID id){var record=new ConsumerRecord<String,String>("usage",3,19,"key","{}");record.headers().add(new RecordHeader("event-id",id.toString().getBytes(StandardCharsets.UTF_8)));return record;}
}
